json = {
    "output": {
      "metadata_targets": [
        {
          "target_metadata_key": "COLLABORATION_STYLE",
          "target_values_to_fetch": [
            "Independent worker"
          ],
          "justification": "Testing the boundary condition where individuals with strong independent work styles may resist, undermine, or alternatively find unique ways to engage with formal interdisciplinary team structures. This challenges the property 'structured collaboration' and may reveal tensions between individual autonomy and team integration."
        },
        {
          "target_metadata_key": "AI_INTEGRATION_LEVEL",
          "target_values_to_fetch": [
            "Non-user/resister"
          ],
          "justification": "Testing the negative case where organizations or individuals resisting AI adoption altogether likely do not engage in building interdisciplinary AI teams. This probes the category's assumption that team-building is a strategic approach to integration, revealing contexts where integration is rejected rather than strategically pursued."
        },
        {
          "target_metadata_key": "Tamaño del medio",
          "target_values_to_fetch": [
            "Pequeño"
          ],
          "justification": "Testing the boundary condition of resource scarcity and structural constraints. Small organizations may lack the personnel, budget, or formal hierarchy to create dedicated interdisciplinary teams, potentially forcing reliance on informal networks or individual multifunctional roles, thus testing the property 'varies in structural complexity and organizational commitment levels'."
        },
        {
          "target_metadata_key": "ORGANIZATIONAL_PERSPECTIVE",
          "target_values_to_fetch": [
            "Operational implementer"
          ],
          "justification": "Testing the dimension of organizational vantage point. Operational implementers experience team dynamics at the ground level, potentially revealing friction points, role ambiguity, and practical obstacles to 'clear roles, shared objectives' that strategic decision-makers may not see. This tests the implementation optimization purpose."
        },
        {
          "target_metadata_key": "team_formality_continuum",
          "target_values_to_fetch": [
            "Informal emergent network",
            "Highly formalized matrix structure"
          ],
          "justification": "A proposed theoretical variable capturing the degree of institutionalization. Sampling extreme ends tests the category's middle-position claim on the formality continuum. Highly formal structures may reveal bureaucratic rigidity, while informal networks may show fluid collaboration but lack deliberate creation—challenging the definition's core."
        },
        {
          "target_metadata_key": "interdisciplinary_power_dynamics",
          "target_values_to_fetch": [
            "Journalistic domain dominance",
            "Technical domain dominance",
            "Balanced power sharing"
          ],
          "justification": "A proposed theoretical variable capturing authority and influence distribution between domains. The category assumes integration, but power imbalances (e.g., technologists dictating tools vs journalists dictating needs) could fundamentally alter team function, decision-making, and outcome, testing the 'cross-domain integration of expertise' property."
        },
        {
          "target_metadata_key": "resource_allocation_mechanism",
          "target_values_to_fetch": [
            "Centralized strategic budget",
            "Decentralized project-based",
            "Ad-hoc/no dedicated resources"
          ],
          "justification": "A proposed theoretical variable for funding and resource provision. Mechanism determines team sustainability, scope, and authority. Ad-hoc or decentralized models may produce temporary, unstable teams, challenging the 'deliberate creation of formal teams' and testing the developmental trajectory property."
        }
      ]
    }
  }


r = []
for i in json["output"]["metadata_targets"]:
  key = i["target_metadata_key"]
  vals = i["target_values_to_fetch"]
  jus = i["justification"]
  r.append({"cat":"Building Interdisciplinary Teams","key":key,"vals":vals,"jus":jus})

